from modele import chapitre,E,Q,tableau
from pedagogie import page,bloc

chapitre(1,'grands-nombres','Les nombres jusqu’au milliard','1 · Nombres entiers et calculs',
'Millions · Classes · Comparaisons · Demi-droite',
['Lire, écrire et décomposer les nombres jusqu’à neuf chiffres.','Comparer, encadrer et intercaler de grands nombres.','Placer et lire des nombres sur une demi-droite graduée.'],
['Numération jusqu’à 999 999 (classe des mille).'],[
page(1,'La classe des millions',
bloc('definition',r'Après la classe des unités simples et la classe des mille vient la classe des millions : unités, dizaines et centaines de millions. Le nombre $45\,208\,316$ se lit « quarante-cinq-millions-deux-cent-huit-mille-trois-cent-seize ».')+
tableau(['Classe','des millions','des mille','des unités'],[['Rangs','c d u','c d u','c d u'],[r'$45\,208\,316$','0 4 5','2 0 8','3 1 6']]),
bloc('propriete',r'Chaque rang vaut dix fois le rang placé à sa droite : un million, c’est mille milliers, soit dix centaines de mille. Les zéros gardent la place des rangs vides : $305\,000\,420$ contient 5 unités de millions et aucune dizaine de mille.'),
bloc('exemple',r'$45\,208\,316=45\times1\,000\,000+208\times1\,000+316$. On peut aussi décomposer chiffre par chiffre : $4\times10\,000\,000+5\times1\,000\,000+2\times100\,000+8\times1\,000+3\times100+1\times10+6$.'),
bloc('savoirfaire',r'Dans $45\,208\,316$, le chiffre des dizaines de mille est 0, mais le nombre de milliers est $45\,208$ : tous les paquets de mille contenus. Cette lecture par paquets sert pour les échanges et les ordres de grandeur.','Chiffre ou nombre')),
page(2,'Comparer et placer les grands nombres',
bloc('propriete',r'Pour comparer deux entiers : le moins long est le plus petit ; à longueur égale, comparer rang par rang depuis la gauche. $9\,987\,654<10\,000\,000$ : sept chiffres contre huit.'),
r'@FIG:cours-droite-millions@',
bloc('savoirfaire',r'Encadrer $7\,802\,540$ entre deux millions consécutifs : $7\,000\,000<7\,802\,540<8\,000\,000$. À la centaine de mille près : $7\,800\,000<7\,802\,540<7\,900\,000$. Le rang demandé fixe les bornes.','Encadrer au rang demandé'),
bloc('attention',r'Les espaces séparent les classes par paquets de trois chiffres, en partant de la droite : ils aident la lecture mais ne changent pas le nombre. Sur une demi-droite, lire la valeur d’un intervalle avant de placer quoi que ce soit.'))
],[
E('Écrire en chiffres',r'Écrire en chiffres : « trois-millions-quarante-mille-deux-cents » ; « soixante-millions-cinq-cent-mille » ; « huit-cent-millions-neuf ».',r'On remplit classe par classe : $\res{3\,040\,200}$, $\res{60\,500\,000}$ et $\res{800\,000\,009}$.','Compléter chaque classe avec trois chiffres.','assert 3*1000000+40*1000+200==3040200 and 60*1000000+500*1000==60500000 and 800*1000000+9==800000009'),
E('Lire par classes',r'Écrire en lettres $45\,208\,316$, puis donner sa classe des mille.',r'« $\res{\text{quarante-cinq-millions-deux-cent-huit-mille-trois-cent-seize}}$ ». La classe des mille porte $\res{208}$.','Lire chaque classe suivie de son nom.','assert 45*1000000+208*1000+316==45208316'),
E('La valeur des chiffres',r'Dans $305\,000\,420$, donner le chiffre des unités de millions, puis la valeur du chiffre 3.',r'Le chiffre des unités de millions est $\res5$. Le 3 occupe les centaines de millions : il vaut $\res{300\,000\,000}$.','Repérer la classe avant le rang.','assert (305000420//1000000)%10==5 and 305000420//100000000==3'),
E('Nombre de milliers',r'Pour $45\,208\,316$ : quel est le chiffre des unités de mille ? Combien ce nombre contient-il de milliers entiers ?',r'Le chiffre des unités de mille est $\res8$. Le nombre de milliers est $\res{45\,208}$, car $45\,208\,316=45\,208\times1\,000+316$.','Séparer les trois derniers chiffres.','assert (45208316//1000)%10==8 and 45208316//1000==45208'),
E('Comparer',r'Compléter par $<$ ou $>$ : $9\,987\,654\ \ldots\ 10\,000\,000$, puis $45\,320\,000\ \ldots\ 45\,230\,000$.',r'Sept chiffres contre huit : $\res{9\,987\,654<10\,000\,000}$. À longueur égale, les centaines de mille tranchent : $\res{45\,320\,000>45\,230\,000}$.','Compter les chiffres puis comparer rang à rang.','assert 9987654<10000000 and 45320000>45230000'),
E('Décomposer et recomposer',r'Décomposer $7\,080\,205$ avec les valeurs de chaque chiffre, puis écrire le nombre $6\times10\,000\,000+3\times10\,000+5\times100$.',r'$7\,080\,205=\res{7\times1\,000\,000+8\times10\,000+2\times100+5}$. La recomposition donne $\res{60\,030\,500}$.','N’écrire que les rangs non nuls.','assert 7*1000000+8*10000+2*100+5==7080205 and 6*10000000+3*10000+5*100==60030500'),
E('Sur la demi-droite',r'Lire les nombres repérés par A, B et C sur la demi-droite graduée.',r'Deux graduations marquées voisines diffèrent de un million ; chaque petit pas vaut $200\,000$. On lit $\res{A(3\,200\,000)}$, $\res{B(4\,600\,000)}$ et $\res{C(5\,800\,000)}$.','Chercher la valeur d’un petit intervalle.','assert 3000000+200000==3200000 and 4000000+3*200000==4600000 and 6000000-200000==5800000',figure='num-7'),
E('Encadrer',r'Encadrer $7\,802\,540$ entre deux millions consécutifs, puis entre deux dizaines de mille consécutives.',r'$\res{7\,000\,000<7\,802\,540<8\,000\,000}$ et $\res{7\,800\,000<7\,802\,540<7\,810\,000}$.','Fixer le rang, puis prendre ses deux multiples voisins.','assert 7000000<7802540<8000000 and 7800000<7802540<7810000'),
E('Intercaler',r'Donner un nombre compris entre $64\,999\,000$ et $65\,001\,000$, dont le chiffre des centaines est 4.',r'Par exemple $\res{65\,000\,400}$ : il est entre les deux bornes et son chiffre des centaines est 4. D’autres choix conviennent.','Caler d’abord les classes, puis le rang imposé.','assert 64999000<65000400<65001000 and (65000400//100)%10==4'),
E('Ordonner',r'Ranger dans l’ordre décroissant : $9\,900\,000$ ; $10\,100\,000$ ; $9\,090\,000$ ; $10\,010\,000$.',r'Les nombres à huit chiffres dominent : $\res{10\,100\,000>10\,010\,000>9\,900\,000>9\,090\,000}$.','Grouper par longueur avant de comparer.','assert sorted([9900000,10100000,9090000,10010000],reverse=True)==[10100000,10010000,9900000,9090000]'),
E('Les populations',r'Quatre pays comptent $67\,800\,000$, $47\,400\,000$, $83\,200\,000$ et $10\,500\,000$ habitants. Ranger ces populations dans l’ordre croissant, puis encadrer la plus grande entre deux dizaines de millions consécutives.',r'L’ordre croissant est $\res{10\,500\,000<47\,400\,000<67\,800\,000<83\,200\,000}$. La plus grande vérifie $\res{80\,000\,000<83\,200\,000<90\,000\,000}$.','Comparer les dizaines de millions d’abord.','assert sorted([67800000,47400000,83200000,10500000])==[10500000,47400000,67800000,83200000] and 80000000<83200000<90000000'),
E('Des paquets de mille',r'Un entrepôt doit expédier $2\,507\,000$ brochures en cartons de $1\,000$. Combien de cartons remplit-il ? Et s’il reçoit encore 500 brochures ?',r'$2\,507\,000=2\,507\times1\,000$ : $\res{2\,507}$ cartons exactement. Avec 500 brochures de plus, un carton reste incomplet : toujours $\res{2\,507}$ cartons pleins et 500 brochures en attente.','Compter les milliers entiers.','assert 2507000//1000==2507 and (2507000+500)//1000==2507'),
E('Le compteur du site',r'Un site affiche $9\,999\,500$ visites. Combien de visites manquent pour atteindre dix millions ? Quel nombre affichera le compteur 800 visites plus tard ?',r'Il manque $10\,000\,000-9\,999\,500=\res{500}$ visites. Après 800 visites : $9\,999\,500+800=\res{10\,000\,300}$ : le cap des huit chiffres est franchi.','S’appuyer sur le passage au rang supérieur.','assert 10000000-9999500==500 and 9999500+800==10000300'),
E('Avec six cartes',r'Avec les cartes 5, 0, 8, 2, 9 et 1 utilisées chacune une fois, écrire le plus grand nombre possible, puis le plus petit nombre à six chiffres.',r'Ordre décroissant : $\res{985\,210}$. Pour le plus petit, commencer par le plus petit chiffre non nul : $\res{102\,589}$.','Choisir le chiffre de gauche en premier.',"assert ''.join(sorted('508291',reverse=True))=='985210' and ''.join(sorted('508291'))=='012589' and 102589==int('1'+'02589')"),
E('Vrai ou faux ?',r'Lina affirme : « $9\,999\,999$ est plus grand que $10\,000\,001$ car il contient plus de 9. » Corriger son raisonnement, puis donner l’écart entre les deux nombres.',r'On compare d’abord les longueurs : sept chiffres contre huit, donc $\res{9\,999\,999<10\,000\,001}$. Les chiffres utilisés ne décident pas. L’écart vaut $10\,000\,001-9\,999\,999=\res2$.','Compter les chiffres avant tout.','assert 9999999<10000001 and 10000001-9999999==2')
],reperes=['Classes des millions et lectures','Décompositions et valeurs','Comparer, encadrer, intercaler','Demi-droite et problèmes'],deco='calcul'),

chapitre(2,'operations-entiers','Additionner, soustraire, multiplier','1 · Nombres entiers et calculs',
'Techniques posées · Calcul réfléchi · Parenthèses',
['Poser et contrôler sommes, différences et produits.','Calculer de tête avec des procédures expliquées.','Respecter les parenthèses dans un calcul.'],
['Les quatre opérations du CM1.'],[
page(1,'Consolider les techniques',
bloc('savoirfaire',r'Aligner les rangs, gérer les retenues, estimer avant de calculer : $38\,675+4\,850$ est proche de $38\,700+4\,900=43\,600$ ; le calcul posé donne $43\,525$. Une soustraction se contrôle par l’addition : $70\,200-2\,460=67\,740$ car $67\,740+2\,460=70\,200$.','Poser, estimer, contrôler'),
bloc('exemple',r'$485\times36$ : $485\times6=2\,910$ et $485\times30=14\,550$ ; la somme donne $17\,460$. L’estimation $500\times35=17\,500$ confirme l’ordre de grandeur.'),
bloc('propriete',r'Multiplier des nombres ronds : $300\times40=12\,000$, car $3\times4=12$ suivi des trois zéros. Cette règle vient des rangs : des centaines multipliées par des dizaines donnent des milliers.'),
bloc('savoirfaire',r'Ajouter ou retirer 98 ou 99 : passer par 100. $457+99=457+100-1=556$ ; $623-98=623-100+2=525$. Les doubles aident aussi : $36+37=36+36+1=73$.','Des procédures de tête')),
page(2,'Les parenthèses',
bloc('definition',r'Les parenthèses s’effectuent d’abord : $5\times(12-4)=5\times8=40$, alors que $5\times12-4=56$. Elles peuvent s’emboîter par paires : $(20-(3+5))\times2=(20-8)\times2=24$.'),
bloc('exemple',r'Traduire « le double de la somme de 8 et 7 » : $2\times(8+7)=30$. Sans parenthèses, $2\times8+7=23$ dit autre chose : « le double de 8, puis 7 de plus ».'),
bloc('savoirfaire',r'Dans un calcul à étapes, écrire une ligne par transformation et recopier ce qui ne change pas : $(35+15)\times(9-5)=50\times4=200$.','Une ligne par étape'),
bloc('attention',r'Une expression se lit en entier avant de calculer. Repérer les paires de parenthèses : chaque ouvrante a sa fermante, et l’intérieur se traite en premier.'))
],[
E('Deux sommes posées',r'Poser et calculer $38\,675+4\,850$ et $256\,908+87\,314$.',r'$38\,675+4\,850=\res{43\,525}$ et $256\,908+87\,314=\res{344\,222}$. Estimations : $43\,500$ et $344\,000$ environ.','Aligner les rangs et estimer.','assert 38675+4850==43525 and 256908+87314==344222'),
E('Deux différences posées',r'Poser et calculer $70\,200-2\,460$ et $500\,000-123\,456$.',r'$70\,200-2\,460=\res{67\,740}$ ; contrôle : $67\,740+2\,460=70\,200$. Et $500\,000-123\,456=\res{376\,544}$.','Contrôler par l’addition.','assert 70200-2460==67740 and 500000-123456==376544 and 376544+123456==500000'),
E('Presque cent',r'Calculer de tête $457+99$, $623-98$ et $350+198$.',r'$457+100-1=\res{556}$ ; $623-100+2=\res{525}$ ; $350+200-2=\res{548}$.','Passer par la centaine la plus proche.','assert 457+99==556 and 623-98==525 and 350+198==548'),
E('Des nombres ronds',r'Calculer $300\times40$, $70\times800$ et $600\times50$.',r'$3\times4=12$ puis trois zéros : $\res{12\,000}$. $7\times8=56$ puis trois zéros : $\res{56\,000}$. $6\times5=30$ puis trois zéros : $\res{30\,000}$ ; le zéro de 30 s’ajoute.','Multiplier les chiffres, compter les zéros.','assert 300*40==12000 and 70*800==56000 and 600*50==30000'),
E('Un produit posé',r'Poser et calculer $485\times36$.',r'$485\times6=2\,910$ ; $485\times30=14\,550$ ; somme : $\res{17\,460}$. Estimation : $500\times35=17\,500$.','Séparer unités et dizaines du multiplicateur.','assert 485*6==2910 and 485*30==14550 and 485*36==17460'),
E('Les parenthèses d’abord',r'Calculer $5\times(12-4)$, puis $5\times12-4$. Pourquoi les résultats diffèrent-ils ?',r'$5\times(12-4)=5\times8=\res{40}$ ; $5\times12-4=60-4=\res{56}$. Les parenthèses imposent de soustraire avant de multiplier : l’ordre des actions change le résultat.','Traiter l’intérieur des parenthèses en premier.','assert 5*(12-4)==40 and 5*12-4==56'),
E('Deux paires',r'Calculer $(35+15)\times(9-5)$, puis $(20-(3+5))\times2$.',r'$50\times4=\res{200}$. Pour la seconde : la parenthèse intérieure donne 8, puis $(20-8)\times2=12\times2=\res{24}$.','Commencer par la parenthèse la plus intérieure.','assert (35+15)*(9-5)==200 and (20-(3+5))*2==24'),
E('Traduire une phrase',r'Écrire en une seule expression puis calculer : « le triple de la différence entre 40 et 13 ».',r'La différence vaut $40-13$ ; son triple s’écrit $\res{3\times(40-13)}=3\times27=\res{81}$. Sans parenthèses, $3\times40-13=107$ dirait autre chose.','Encadrer la quantité décrite avant de multiplier.','assert 3*(40-13)==81 and 3*40-13==107'),
E('La bonne expression',r'Trois amis achètent chacun un sandwich à 4 euros et une boisson à 2 euros. Parmi $3\times4+2$ et $3\times(4+2)$, choisir l’expression qui donne la dépense totale, puis calculer.',r'Chacun dépense $4+2$ euros : il faut $\res{3\times(4+2)}=18$ euros. L’expression $3\times4+2=14$ compterait une seule boisson.','Chercher ce que paie une seule personne.','assert 3*(4+2)==18 and 3*4+2==14'),
E('Compléter les étapes',r'Compléter : $56\times\square=5\,600$ ; $\square-4\,500=12\,800$ ; $7\times\square=4\,900$.',r'$56\times\res{100}=5\,600$ ; $12\,800+4\,500=\res{17\,300}$ ; $4\,900:7=\res{700}$.','Choisir l’opération qui défait l’autre.','assert 56*100==5600 and 17300-4500==12800 and 7*700==4900'),
E('Le festival',r'Un festival a vendu $12\,760$ billets le samedi et $9\,845$ le dimanche. La salle pouvait accueillir $25\,000$ personnes au total sur le week-end. Combien de places sont restées libres ?',r'Billets vendus : $12\,760+9\,845=22\,605$. Places libres : $25\,000-22\,605=\res{2\,395}$. L’estimation $12\,800+9\,800=22\,600$ confirme la somme.','Additionner avant de comparer à la capacité.','assert 12760+9845==22605 and 25000-22605==2395'),
E('La commande de la mairie',r'La mairie commande 36 tables à 485 euros l’une et 144 chaises à 59 euros l’une. Quel est le montant total de la commande ?',r'Tables : $485\times36=17\,460$ euros. Chaises : $59\times144=8\,496$ euros. Total : $17\,460+8\,496=\res{25\,956}$ euros.','Calculer chaque produit avant la somme.','assert 485*36==17460 and 59*144==8496 and 17460+8496==25956'),
E('Une facture à vérifier',r'Une facture annonce : « 24 cartouches à 18 euros : 532 euros ». Vérifier par une estimation puis par le calcul exact, et corriger si besoin.',r'Estimation : $24\times18$ est proche de $25\times18=450$ : 532 semble trop grand. Calcul exact : $24\times18=\res{432}$ euros ; la facture $\res{\text{est fausse}}$ de 100 euros.','Estimer avant de refaire le calcul exact.','assert 24*18==432 and 532-432==100'),
E('Le double piège',r'Zoé calcule $2\times15+5=40$ et Tom calcule $2\times(15+5)=40$. L’un des deux se trompe : lequel ? Donner les deux bons résultats.',r'$2\times15+5=30+5=\res{35}$ : c’est Zoé qui se trompe. $2\times(15+5)=2\times20=\res{40}$ : Tom a raison. Même écriture sans parenthèses, autre sens.','Refaire chaque calcul en respectant les priorités.','assert 2*15+5==35 and 2*(15+5)==40'),
E('Le tour de magie',r'Un magicien annonce : « Choisis un nombre, ajoute 25, retire 17, retire ton nombre de départ : je connais ton résultat ! » Tester avec 40 et avec 358, puis expliquer.',r'Avec 40 : $40+25-17-40=\res8$. Avec 358 : $358+25-17-358=\res8$. Le nombre choisi s’ajoute puis se retire : il disparaît du bilan, qui vaut toujours $25-17=8$.','Suivre ce que devient le nombre choisi.','assert 40+25-17-40==8 and 358+25-17-358==8 and 25-17==8')
],reperes=['Techniques posées et contrôles','Calcul réfléchi','Parenthèses et expressions','Problèmes et factures'],deco='calcul'),

chapitre(3,'multiples-diviseurs','Multiples, diviseurs et partages','1 · Nombres entiers et calculs',
'Critères · Listes de diviseurs · Communs',
['Reconnaître multiples et diviseurs, avec les critères par 2, 5 et 10.','Trouver tous les diviseurs d’un nombre jusqu’à 30.','Chercher des diviseurs ou des multiples communs.'],
['Tables de multiplication et division euclidienne.'],[
page(1,'Multiples et diviseurs',
bloc('definition',r'Comme $56=8\times7$, le nombre 56 est un multiple de 8 et de 7 ; et 8 et 7 sont des diviseurs de 56 : le partage tombe juste, le reste de la division est nul.'),
bloc('propriete',r'Critères sur le chiffre des unités : multiple de 2 s’il finit par 0, 2, 4, 6, 8 ; multiple de 5 s’il finit par 0 ou 5 ; multiple de 10 s’il finit par 0. Pour les autres diviseurs, on utilise les tables ou une division.'),
bloc('exemple',r'7 divise-t-il 91 ? $7\times13=91$ : oui. 6 divise-t-il 92 ? $92=6\times15+2$ : non, le reste vaut 2.'),
bloc('savoirfaire',r'Un nombre proche peut aider : 91 est à côté de 90, multiple de 5 et de 10 ; mais 91 finit par 1 : il n’est multiple ni de 2, ni de 5, ni de 10. Les critères se lisent sur le nombre lui-même.','Lire le chiffre des unités')),
page(2,'Trouver tous les diviseurs',
bloc('savoirfaire',r'Pour lister tous les diviseurs de 24, chercher les paires de facteurs : $1\times24$, $2\times12$, $3\times8$, $4\times6$. La liste complète est 1, 2, 3, 4, 6, 8, 12, 24 : rien n’est oublié, car les paires épuisent les cas.','Des paires de facteurs'),
bloc('exemple',r'Diviseurs de 18 : 1, 2, 3, 6, 9, 18. Diviseurs de 24 : 1, 2, 3, 4, 6, 8, 12, 24. Les diviseurs communs aux deux nombres sont 1, 2, 3 et 6 : ils permettent des partages identiques des deux collections.'),
bloc('propriete',r'Les multiples communs servent aux rendez-vous réguliers : les multiples de 6 sont 6, 12, 18, 24… ; ceux de 8 sont 8, 16, 24… Le plus petit multiple commun non nul de 6 et 8 est 24.'),
bloc('attention',r'1 divise tous les nombres, et chaque nombre est son propre plus grand diviseur. Une liste de diviseurs se vérifie : chaque candidat doit donner un reste nul.'))
],[
E('Multiples à repérer',r'Écrire les cinq premiers multiples non nuls de 7, puis dire si 84 est un multiple de 7.',r'$7, 14, 21, 28, 35$. Et $7\times12=84$ : $\res{\text{oui}}$, 84 est un multiple de 7.','Compter de 7 en 7 ou utiliser un produit.','assert [7*k for k in range(1,6)]==[7,14,21,28,35] and 84%7==0'),
E('Les critères des unités',r'Parmi 230, 345, 1\,308 et 95, lesquels sont multiples de 2 ? de 5 ? de 10 ?',r'Multiples de 2 : $\res{230\text{ et }1\,308}$. Multiples de 5 : $\res{230,\ 345,\ 95}$. Multiples de 10 : $\res{230}$ seulement.','Lire uniquement le chiffre des unités.','assert [a for a in [230,345,1308,95] if a%2==0]==[230,1308] and [a for a in [230,345,1308,95] if a%5==0]==[230,345,95] and [a for a in [230,345,1308,95] if a%10==0]==[230]'),
E('Diviseur ou pas ?',r'8 est-il un diviseur de 96 ? 7 est-il un diviseur de 93 ?',r'$8\times12=96$ : $\res{\text{oui}}$. $93=7\times13+2$ : $\res{\text{non}}$, le reste vaut 2.','Chercher un produit exact ou poser la division.','assert 96%8==0 and 93%7==2'),
E('Tous les diviseurs',r'Écrire la liste complète des diviseurs de 24, en t’aidant des paires de facteurs.',r'$1\times24$, $2\times12$, $3\times8$, $4\times6$ : la liste est $\res{1, 2, 3, 4, 6, 8, 12, 24}$.','Balayer les facteurs dans l’ordre croissant.','assert divisors(24)==[1,2,3,4,6,8,12,24]'),
E('Pairs et impairs',r'Sans calculer, dire si chaque somme est paire ou impaire : $346+58$ ; $127+41$ ; $230+87$.',r'Pair plus pair : $\res{\text{paire}}$. Impair plus impair : $\res{\text{paire}}$. Pair plus impair : $\res{\text{impaire}}$. Les paquets de deux expliquent ces règles.','Raisonner sur les paquets de deux.','assert (346+58)%2==0 and (127+41)%2==0 and (230+87)%2==1'),
E('Diviseurs de 30 et 18',r'Lister les diviseurs de 30, puis ceux de 18, puis leurs diviseurs communs.',r'Diviseurs de 30 : $1,2,3,5,6,10,15,30$. Diviseurs de 18 : $1,2,3,6,9,18$. Les diviseurs communs sont $\res{1, 2, 3, 6}$.','Comparer les deux listes complètes.','assert divisors(30)==[1,2,3,5,6,10,15,30] and divisors(18)==[1,2,3,6,9,18] and [d for d in divisors(18) if 30%d==0]==[1,2,3,6]'),
E('Multiples communs',r'Écrire les multiples de 6 jusqu’à 50, puis ceux de 8. Quel est leur plus petit multiple commun non nul ?',r'Multiples de 6 : 6, 12, 18, 24, 30, 36, 42, 48. Multiples de 8 : 8, 16, 24, 32, 40, 48. Les communs sont 24 et 48 ; le plus petit est $\res{24}$.','Comparer les deux listes de multiples.','assert ilcm(6,8)==24 and [a for a in range(1,51) if a%6==0 and a%8==0]==[24,48]'),
E('Un chiffre à choisir',r'Trouver tous les chiffres $\square$ pour que $47\square$ soit un multiple de 5. Et pour qu’il soit un multiple de 10 ?',r'Multiple de 5 : le nombre doit finir par 0 ou 5, donc $\square=\res{0\text{ ou }5}$. Multiple de 10 : $\square=\res0$ seulement.','Appliquer les critères au chiffre des unités.','assert [a for a in range(10) if (470+a)%5==0]==[0,5] and [a for a in range(10) if (470+a)%10==0]==[0]'),
E('Le reste raconte',r'La division de 125 par 6 donne $125=6\times20+5$. 6 est-il un diviseur de 125 ? Quel est le plus proche multiple de 6 au-dessus de 125 ?',r'Le reste vaut 5, pas 0 : 6 $\res{\text{ne divise pas}}$ 125. Le multiple suivant est $6\times21=\res{126}$.','Relier reste nul et diviseur.','assert 125%6==5 and 6*21==126'),
E('Vrai ou faux ?',r'« Tout multiple de 10 est aussi un multiple de 5. » « Tout multiple de 5 est aussi un multiple de 10. » Justifier chaque réponse.',r'La première est $\res{\text{vraie}}$ : un nombre fini par 0 est aussi fini par 0 ou 5 ; $10=5\times2$, donc dix paquets de 5. La seconde est $\res{\text{fausse}}$ : 15 est multiple de 5 mais pas de 10.','Chercher un contre-exemple pour réfuter.','assert 15%5==0 and 15%10!=0 and all(a%5==0 for a in [10,20,30])'),
E('Les bouquets',r'Une fleuriste a 24 roses et 18 tulipes. Elle veut des bouquets tous identiques, sans fleur restante. Combien de bouquets peut-elle faire ? Donner toutes les possibilités, puis la composition avec 6 bouquets.',r'Le nombre de bouquets doit diviser 24 et 18 : $\res{1, 2, 3\text{ ou }6}$ bouquets. Avec 6 bouquets : $24:6=\res4$ roses et $18:6=\res3$ tulipes chacun.','Chercher les diviseurs communs des deux effectifs.','assert [d for d in divisors(18) if 24%d==0]==[1,2,3,6] and 24//6==4 and 18//6==3'),
E('Les deux phares',r'Un phare s’allume toutes les 12 secondes, un autre toutes les 9 secondes. Ils viennent de s’allumer ensemble. Dans combien de secondes s’allumeront-ils de nouveau ensemble ?',r'Multiples de 12 : 12, 24, 36… Multiples de 9 : 9, 18, 27, 36… Le premier commun est $\res{36}$ secondes.','Chercher le plus petit multiple commun.','assert ilcm(12,9)==36'),
E('Les rangées du verger',r'Un jardinier plante 90 arbres en rangées égales. Peut-il faire des rangées de 5 arbres ? de 6 ? de 7 ? Donner à chaque fois le nombre de rangées ou le reste.',r'$90=5\times18$ : $\res{18}$ rangées exactes. $90=6\times15$ : $\res{15}$ rangées exactes. $90=7\times12+6$ : impossible sans reste, il resterait $\res6$ arbres.','Tester chaque diviseur par une division.','assert 90%5==0 and 90//5==18 and 90//6==15 and divmod(90,7)==(12,6)'),
E('Le nombre secret',r'Je suis un diviseur de 24, je suis pair, je suis un multiple de 3 et je suis plus petit que 10. Qui suis-je ? Expliquer pourquoi la réponse est unique.',r'Diviseurs de 24 : 1, 2, 3, 4, 6, 8, 12, 24. Les pairs multiples de 3 sont 6, 12 et 24 : trois candidats. La dernière contrainte, « plus petit que 10 », ne laisse que $\res6$. Chaque indice d’une devinette élimine des candidats, jusqu’à n’en garder qu’un.','Lister puis filtrer les candidats.','assert [d for d in divisors(24) if d%2==0 and d%3==0]==[6,12,24] and [d for d in divisors(24) if d%2==0 and d%3==0 and d<10]==[6]'),
E('Toujours vrai ?',r'Milo affirme : « La somme de trois multiples de 5 est toujours un multiple de 5. » Tester sur un exemple, puis expliquer avec des paquets de cinq.',r'Exemple : $10+25+40=\res{75}=5\times15$. Chaque terme est fait de paquets de cinq ; leur réunion aussi : l’affirmation est $\res{\text{toujours vraie}}$. L’argument vaut pour tous les choix, pas seulement l’exemple.','Dépasser l’exemple par l’argument des paquets.','assert 10+25+40==75 and 75%5==0')
],reperes=['Multiples et critères','Listes complètes de diviseurs','Diviseurs et multiples communs','Partages et rendez-vous'],deco='calcul')
